"""
Global Library callbacks for Open Photo Agent.

This module provides Dash callbacks for the Global Library feature,
enabling cross-folder search, tag browsing, and vector similarity matching.
"""

import dash
import dash_bootstrap_components as dbc
from dash import Input, Output, State, html, callback_context
from dash.exceptions import PreventUpdate

from src.global_library.database import GlobalLibraryDatabase
from src.global_library.indexer import GlobalIndexer
from src.global_library.search import GlobalSearch
from src.constants import (
    GLOBAL_LIBRARY_DISABLED,
    GLOBAL_MODE_ENABLED,
    GLOBAL_MODE_DISABLED,
    NO_FOLDERS_INDEXED,
    FOLDER_ADDED_TO_LIBRARY,
    FOLDER_REMOVED_FROM_LIBRARY,
    INDEXING_COMPLETE,
)

# Module-level instances
_global_db = None
_global_indexer = None
_global_search = None


def get_global_db() -> GlobalLibraryDatabase:
    """Get or create the global database instance."""
    global _global_db
    if _global_db is None:
        _global_db = GlobalLibraryDatabase()
    return _global_db


def get_global_indexer() -> GlobalIndexer:
    """Get or create the global indexer instance."""
    global _global_indexer
    if _global_indexer is None:
        _global_indexer = GlobalIndexer()
    return _global_indexer


def get_global_search() -> GlobalSearch:
    """Get or create the global search instance."""
    global _global_search
    if _global_search is None:
        _global_search = GlobalSearch()
    return _global_search


def register_global_library_callbacks(app):
    """Register all Global Library callbacks with the Dash app."""

    # Callback to toggle global mode
    @app.callback(
        Output("global-mode-toggle", "value"),
        Output("global-mode-status", "children"),
        Input("global-mode-toggle", "value"),
        prevent_initial_call=True,
    )
    def toggle_global_mode(enabled):
        """Toggle global library mode on/off."""
        if callback_context.triggered:
            if enabled:
                return True, html.Div(GLOBAL_MODE_ENABLED, className="text-success")
            else:
                return False, html.Div(GLOBAL_MODE_DISABLED, className="text-muted")
        raise PreventUpdate

    # Callback to list indexed folders
    @app.callback(
        Output("global-library-folders", "children"),
        Input("global-mode-toggle", "value"),
        Input("btn-refresh-library", "n_clicks"),
        prevent_initial_call=True,
    )
    def list_indexed_folders(enabled, n_clicks):
        """List all folders currently in the global library."""
        if not enabled:
            return html.Div("Global Library is disabled", className="text-muted")

        try:
            indexer = get_global_indexer()
            folders = indexer.list_indexed_folders()

            if not folders:
                return html.Div(NO_FOLDERS_INDEXED, className="text-warning")

            folder_items = []
            for folder in folders:
                folder_path = folder.get("folder_path", "Unknown")
                photo_count = folder.get("photo_count", 0)
                enabled = folder.get("enabled", 1)

                status = "✓" if enabled else "✗"
                folder_items.append(
                    html.Li(
                        [
                            html.Span(f"{status} ", className="me-2"),
                            html.Span(folder_path, className="me-2"),
                            html.Span(f"({photo_count} photos)", className="text-muted small"),
                            dbc.Button(
                                "×",
                                id={"type": "remove-folder", "index": folder_path},
                                color="link",
                                size="sm",
                                className="ms-2 p-0",
                                title="Remove from library",
                            ),
                        ],
                        className="list-group-item d-flex align-items-center"
                    )
                )

            return html.Div(
                [
                    html.H6(f"{len(folders)} folders indexed", className="mb-2"),
                    html.Ul(folder_items, className="list-group list-group-flush"),
                ]
            )

        except Exception as e:
            return html.Div(f"Error listing folders: {e}", className="text-danger")

    # Callback to add a folder to the library
    @app.callback(
        Output("global-library-add-result", "children"),
        Output("input-add-folder-path", "value"),
        Input("btn-add-folder", "n_clicks"),
        State("input-add-folder-path", "value"),
        prevent_initial_call=True,
    )
    def add_folder_to_library(n_clicks, folder_path):
        """Add a folder to the global library."""
        if not folder_path:
            return html.Div("Please enter a folder path", className="text-warning"), ""

        try:
            indexer = get_global_indexer()
            success, message, photo_count = indexer.index_folder(folder_path)

            if success:
                return (
                    html.Div(
                        f"{FOLDER_ADDED_TO_LIBRARY}: {message}",
                        className="text-success"
                    ),
                    ""
                )
            else:
                return html.Div(message, className="text-danger"), folder_path

        except Exception as e:
            return html.Div(f"Error adding folder: {e}", className="text-danger"), folder_path

    # Callback to remove a folder from the library
    @app.callback(
        Output("global-library-remove-result", "children"),
        Input({"type": "remove-folder", "index": dash.dependencies.ALL}, "n_clicks"),
        prevent_initial_call=True,
    )
    def remove_folder_from_library(n_clicks):
        """Remove a folder from the global library."""
        if not callback_context.triggered:
            raise PreventUpdate

        button_id = callback_context.triggered[0]["prop_id"]
        if button_id.startswith("{'type': 'remove-folder', 'index': '"):
            # Extract folder path from button ID
            import json
            try:
                button_data = json.loads(button_id.replace("'", '"'))
                folder_path = button_data.get("index")
            except:
                folder_path = None
        else:
            folder_path = None

        if not folder_path:
            raise PreventUpdate

        try:
            indexer = get_global_indexer()
            success, message = indexer.remove_folder(folder_path)

            if success:
                return html.Div(
                    f"{FOLDER_REMOVED_FROM_LIBRARY}: {folder_path}",
                    className="text-success"
                )
            else:
                return html.Div(message, className="text-danger")

        except Exception as e:
            return html.Div(f"Error removing folder: {e}", className="text-danger")

    # Callback to index all folders
    @app.callback(
        Output("global-library-index-result", "children"),
        Input("btn-index-all", "n_clicks"),
        State("input-index-root", "value"),
        prevent_initial_call=True,
    )
    def index_all_folders(n_clicks, root_path):
        """Scan for and index all folders with photo data."""
        if not root_path:
            return html.Div("Please enter a root path to scan", className="text-warning")

        try:
            indexer = get_global_indexer()
            results = indexer.scan_and_index(root_path, recursive=True)

            success_count = results.get("success", 0)
            failed_count = results.get("failed", 0)
            total_photos = results.get("total_photos", 0)
            messages = results.get("messages", [])

            return html.Div(
                [
                    html.Div(f"{INDEXING_COMPLETE}", className="text-success"),
                    html.Ul([html.Li(msg) for msg in messages[:10]]),  # Show first 10 messages
                    html.Div(
                        f"Indexed {success_count} folders, {failed_count} failed, "
                        f"{total_photos} total photos",
                        className="text-muted small"
                    ),
                ]
            )

        except Exception as e:
            return html.Div(f"Error indexing folders: {e}", className="text-danger")

    # Callback to refresh global library stats
    @app.callback(
        Output("global-library-stats", "children"),
        Input("global-mode-toggle", "value"),
        Input("btn-refresh-library", "n_clicks"),
        prevent_initial_call=True,
    )
    def refresh_global_stats(enabled, n_clicks):
        """Refresh and display global library statistics."""
        if not enabled:
            return html.Div("Global Library is disabled", className="text-muted")

        try:
            db = get_global_db()
            stats = db.get_stats()

            return html.Div(
                [
                    html.Span(f"📁 {stats.get('total_folders', 0)} folders", className="me-3"),
                    html.Span(f"🖼️ {stats.get('total_photos', 0)} photos", className="me-3"),
                    html.Span(f"🏷️ {stats.get('total_tags', 0)} tags", className="me-3"),
                    html.Span(f"🔢 {stats.get('total_embeddings', 0)} embeddings"),
                ],
                className="text-muted small"
            )

        except Exception as e:
            return html.Div(f"Error loading stats: {e}", className="text-danger")

